#!/usr/bin/env node
// The language model's evaluation on the 300 held-out situations (the realism work, phase 7, Track L: the research
// "Evaluate"): replies generated by a llama-server on the Mac (b11297, the on-device settings of §3: Qwen's template
// with the empty think block, temperature 0.8, top-k 40, the repetition penalty 1.1 over 64 tokens, top-p 0.9, at most
// 40 tokens, one line of ASCII 32-122 by grammar, the samplers in native's order), then scored by the foundation's
// guard (port/BotModelGuard guardReply) and Track L's checks (checks.mjs: effects, promises, levels, numbers, repeats).
//
//   gen    node eval.mjs gen --server=http://127.0.0.1:8090 --variant=lora|base --out=<file.jsonl> [--prompts=<eval-prompts.jsonl>]
//              [--limit=N] [--seed=1000] [--greedy]
//          `lora`: renderLocal as it is (the fine-tuned model's format); `base`: renderLocal with 6 examples of 2004
//          replies (from the training set) after its system turn, for the base model prompted alone.
//   score  node eval.mjs score [--prompts=<eval-prompts.jsonl>] [--json=<report.json>] [--reference=<replies dir>] <name>=<file.jsonl> ...
//          Scores each generated file and the rules' own lines (the prompts' ruleText) side by side; --reference adds
//          the writers' replies' shape (as many of their training replies, evenly spread) as a yardstick.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { importInEngine } from '../lib/clone.mjs';
import { chatPrompt, chatPromptThink, splitThink } from './chatml.mjs';
import { checkReply } from './checks.mjs';

process.removeAllListeners('warning'); // (the engine's SQLite notice)
const here = path.dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const command = argv[0];
const args = Object.fromEntries(argv.filter(a => a.startsWith('--')).map(a => ((m => (m ? [m[1], m[2] ?? 'true'] : [a, 'true']))(a.match(/^--([^=]+)(?:=(.*))?$/)))));
const positional = argv.slice(1).filter(a => !a.startsWith('--'));
// the held-out prompts: --prompts, else PHASE7_DATA's lm/eval-prompts.jsonl (the training data is not published with the
// repo, so one of them must name a copy of it)
const PROMPTS_ARG = args.prompts ?? (process.env.PHASE7_DATA ? path.join(process.env.PHASE7_DATA, 'lm/eval-prompts.jsonl') : null);
const PROMPTS = PROMPTS_ARG ? path.resolve(PROMPTS_ARG) : null;
function promptsFile() {
    if (!PROMPTS) {
        console.error('eval: --prompts=<phase7-data>/lm/eval-prompts.jsonl (or PHASE7_DATA) is required: the training data is not published with the repo');
        process.exit(2);
    }
    return PROMPTS;
}

const readJsonl = file =>
    fs
        .readFileSync(file, 'utf8')
        .split('\n')
        .filter(l => l.trim())
        .map(l => JSON.parse(l));

/** the base model's examples (training situations s2289, s2522, s2647, s0409, s1180, s2428 and their writers' replies) */
export const FEW_SHOT = [
    'Examples of how other players replied (other chats, not yours: use only your own facts):',
    '"pc on rune med?" (answer idea: 18.5k) -> 18.5k',
    '"i think ur a bot" (answer idea: If I\'m a bot you\'re a goblin) -> think again lol',
    '"where can i fish lobs" (answer idea: theres some on karamja) -> karamja has em, im in the wildy tho',
    '"whats ur fav food" -> pizza!! u?',
    '"whats ur mining lvl" (answer idea: 29 u?) -> only 29, u?',
    '"how long u been on" (answer idea: bout a month) -> bout a month now :)'
].join('\n');

/** the note variant (--think, ): the note in the think block, then the reply; native's two phases
 * (the note free, then the reply's one line by grammar) as one completion: the note and the reply split after it */
function thinkSampling(seed, greedy) {
    return { ...sampling(seed, greedy), n_predict: 100, grammar: undefined, stop: ['<|im_end|>'] };
}

/** §3 "On-device generation" as llama-server takes it */
function sampling(seed, greedy) {
    return {
        n_predict: 40,
        temperature: greedy ? 0 : 0.8,
        top_k: 40,
        top_p: 0.9,
        min_p: 0,
        typical_p: 1,
        repeat_penalty: 1.1,
        repeat_last_n: 64,
        presence_penalty: 0,
        frequency_penalty: 0,
        samplers: ['top_k', 'penalties', 'top_p', 'temperature'],
        grammar: 'root ::= [ -z]{1,120}',
        stop: ['\n', '<|im_end|>'],
        seed,
        cache_prompt: true
    };
}

async function generate() {
    const server = args.server ?? 'http://127.0.0.1:8090';
    const variant = args.variant ?? 'lora';
    if (!['lora', 'base'].includes(variant)) throw new Error(`eval: --variant is lora or base, not ${variant}`);
    const out = path.resolve(args.out ?? `eval-${variant}.jsonl`);
    let rows = readJsonl(promptsFile());
    if (args.limit) rows = rows.slice(0, Number(args.limit));
    const seed0 = Number(args.seed ?? 1000);
    const lines = [];
    const started = Date.now(); // (timing only)
    for (const [i, r] of rows.entries()) {
        const system = variant === 'base' ? `${r.system}\n\n${FEW_SHOT}` : r.system;
        const think = args.think === 'true';
        const body = think ? { prompt: chatPromptThink(system, r.user), ...thinkSampling(seed0 + i, args.greedy === 'true'), special: true } : { prompt: chatPrompt(system, r.user), ...sampling(seed0 + i, args.greedy === 'true') };
        const res = await fetch(`${server}/completion`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
        if (!res.ok) throw new Error(`eval: ${r.id}: HTTP ${res.status} ${await res.text()}`);
        const j = await res.json();
        const split = think ? splitThink(j.content) : null;
        lines.push(
            JSON.stringify({
                id: r.id,
                variant,
                text: think ? split.reply.slice(0, 120) : j.content,
                ...(think ? { note: split.note } : {}),
                tokens: j.tokens_predicted,
                promptTokens: j.tokens_evaluated,
                stop: j.stop_type ?? (j.stopped_eos ? 'eos' : j.stopped_limit ? 'limit' : 'word'),
                promptMs: j.timings?.prompt_ms ?? null,
                genMs: j.timings?.predicted_ms ?? null,
                seed: seed0 + i
            })
        );
        if ((i + 1) % 50 === 0) console.log(`eval gen ${variant}: ${i + 1}/${rows.length} (${Math.round((Date.now() - started) / 1000)} s)`);
    }
    fs.writeFileSync(out, lines.join('\n') + '\n');
    console.log(`eval gen ${variant}: ${lines.length} replies -> ${out} (${Math.round((Date.now() - started) / 1000)} s)`);
}

function words(t) {
    return t.trim().split(/\s+/).filter(Boolean);
}

function distinct(texts, n) {
    let total = 0;
    const seen = new Set();
    for (const t of texts) {
        const w = words(t.toLowerCase().replace(/[^a-z0-9' ]/g, ' '));
        for (let i = 0; i + n <= w.length; i++) {
            seen.add(w.slice(i, i + n).join(' '));
            total++;
        }
    }
    return total ? seen.size / total : 0;
}

const pct = (n, d) => (d ? Math.round((n / d) * 1000) / 10 : 0);
const mean = xs => (xs.length ? Math.round((xs.reduce((a, b) => a + b, 0) / xs.length) * 100) / 100 : 0);
const median = xs => {
    if (!xs.length) return 0;
    const s = [...xs].sort((a, b) => a - b);
    return s[Math.floor(s.length / 2)];
};

/** one variant's replies (raw model text or the rules' lines, by id) scored against their situations */
function scoreVariant(lib, prompts, rawById, meta = new Map()) {
    const reasons = {};
    const checksFailed = {};
    const replies = [];
    const perId = [];
    let answered = 0;
    let guardOk = 0;
    let pass = 0;
    let factBad = 0;
    let named = 0;
    let hintRows = 0;
    let hintKept = 0;
    const tokens = [];
    const genMs = [];
    const promptTokens = [];
    const byVia = {};
    for (const p of prompts) {
        const raw = rawById.get(p.id);
        const via = p.via;
        byVia[via] ??= { n: 0, pass: 0 };
        byVia[via].n++;
        const row = { id: p.id, raw: raw ?? null };
        if (raw == null || !String(raw).trim()) {
            reasons['no reply'] = (reasons['no reply'] ?? 0) + 1;
            row.result = 'no reply';
            perId.push(row);
            continue;
        }
        answered++;
        const m = meta.get(p.id);
        if (m) {
            if (typeof m.tokens === 'number') tokens.push(m.tokens);
            if (typeof m.genMs === 'number') genMs.push(m.genMs);
            if (typeof m.promptTokens === 'number') promptTokens.push(m.promptTokens);
        }
        const g = lib.guardReply(String(raw), p.situation);
        if (!g.ok) {
            reasons[g.reason] = (reasons[g.reason] ?? 0) + 1;
            row.result = `guard: ${g.reason}`;
            perId.push(row);
            continue;
        }
        guardOk++;
        const text = g.text;
        replies.push(text);
        const c = checkReply(p.situation, p.ruleText, text);
        const failedReasons = [...new Set(c.failures.map(f => f.reason))];
        for (const r of failedReasons) checksFailed[r] = (checksFailed[r] ?? 0) + 1;
        if (failedReasons.includes('level') || failedReasons.includes('number')) factBad++;
        if (c.named) named++;
        const hintNumbers = (p.situation.hint?.text.toLowerCase().match(/\b\d+(?:\.\d+)?[km]?\b/g) ?? []).filter(n => n !== '1');
        if (hintNumbers.length) {
            hintRows++;
            if (!c.hintDropped.length) hintKept++;
        }
        if (!failedReasons.length) {
            pass++;
            byVia[via].pass++;
        }
        row.text = text;
        row.result = failedReasons.length ? `checks: ${failedReasons.join(', ')}` : 'pass';
        row.details = c.failures.map(f => `${f.reason}: ${f.detail}`);
        perId.push(row);
    }
    const lens = replies.map(t => t.length);
    const wc = replies.map(t => words(t).length);
    return {
        summary: {
            situations: prompts.length,
            answered,
            answeredPct: pct(answered, prompts.length),
            guardPassPct: pct(guardOk, answered),
            passPct: pct(pass, answered),
            passOfAllPct: pct(pass, prompts.length),
            guardRefusals: reasons,
            checkFailures: checksFailed,
            factContradictions: factBad,
            factContradictionPct: pct(factBad, guardOk),
            chars: { mean: mean(lens), median: median(lens) },
            words: { mean: mean(wc), median: median(wc), '1-3': pct(wc.filter(n => n <= 3).length, wc.length), '4-8': pct(wc.filter(n => n >= 4 && n <= 8).length, wc.length), '9+': pct(wc.filter(n => n >= 9).length, wc.length) },
            lowercasePct: pct(replies.filter(t => t === t.toLowerCase()).length, replies.length),
            distinct1: Math.round(distinct(replies, 1) * 1000) / 1000,
            distinct2: Math.round(distinct(replies, 2) * 1000) / 1000,
            humanNamePct: pct(named, guardOk),
            hintNumbersKeptPct: hintRows ? pct(hintKept, hintRows) : null,
            hintRows,
            replyTokens: tokens.length ? { mean: mean(tokens), median: median(tokens) } : null,
            promptTokens: promptTokens.length ? { mean: mean(promptTokens) } : null,
            genMs: genMs.length ? { mean: mean(genMs), median: median(genMs) } : null,
            passByVia: Object.fromEntries(Object.entries(byVia).map(([k, v]) => [k, `${v.pass}/${v.n}`]))
        },
        perId
    };
}

async function score() {
    const prompts = readJsonl(promptsFile());
    const jsonOut = args.json ? path.resolve(args.json) : null;
    const inputs = positional.map(a => {
        const at = a.indexOf('=');
        if (at < 0) throw new Error(`eval score: name=file, not ${a}`);
        return [a.slice(0, at), path.resolve(a.slice(at + 1))];
    });
    const files = inputs.map(([name, file]) => [name, readJsonl(file)]);
    // (the situations every generated file has: all 300, or the first N of a --limit run)
    const scored = prompts.filter(p => files.every(([, rows]) => rows.some(r => r.id === p.id)));
    const lib = await importInEngine(path.join(here, 'guard-lib.ts'), 'model-eval');
    lib.loadWordEnc();
    const report = {};
    for (const [name, rows] of files) {
        const raw = new Map(rows.map(r => [r.id, r.text]));
        const meta = new Map(rows.map(r => [r.id, r]));
        report[name] = scoreVariant(lib, scored, raw, meta);
    }
    report.rules = scoreVariant(lib, scored, new Map(scored.map(p => [p.id, p.ruleText ? p.ruleText.replaceAll('{name}', p.situation.human.name) : null])));
    if (args.reference) {
        // (the writers' style as a yardstick: as many of their training replies as there are scored situations, every
        // k-th of the 3,000; their situations are not these, so only the shape is compared: length, case, variety)
        const dir = path.resolve(args.reference);
        const all = fs
            .readdirSync(dir)
            .filter(f => /^batch-\d\d\.jsonl$/.test(f))
            .sort()
            .flatMap(f => readJsonl(path.join(dir, f)).map(r => r.reply));
        const byId = new Map(
            fs
                .readdirSync(dir)
                .filter(f => /^batch-\d\d\.jsonl$/.test(f))
                .flatMap(f => readJsonl(path.join(dir, f)).map(r => [r.id, r.reply]))
        );
        if (scored.every(p => byId.has(p.id))) {
            // (the valid set: the writers replied to these very situations, so they are scored like the rest)
            report.writers = scoreVariant(lib, scored, byId);
        }
        const step = Math.max(1, Math.floor(all.length / scored.length));
        const sample = all.filter((_, i) => i % step === 0).slice(0, scored.length);
        const lens = sample.map(t => t.length);
        const wc = sample.map(t => words(t).length);
        if (!report.writers) report.writers = {
            summary: {
                situations: sample.length,
                answered: sample.length,
                answeredPct: 100,
                guardPassPct: '-',
                passPct: '-',
                guardRefusals: {},
                checkFailures: {},
                factContradictions: '-',
                factContradictionPct: '-',
                chars: { mean: mean(lens), median: median(lens) },
                words: { mean: mean(wc), median: median(wc), '1-3': pct(wc.filter(n => n <= 3).length, wc.length), '4-8': pct(wc.filter(n => n >= 4 && n <= 8).length, wc.length), '9+': pct(wc.filter(n => n >= 9).length, wc.length) },
                lowercasePct: pct(sample.filter(t => t === t.toLowerCase()).length, sample.length),
                distinct1: Math.round(distinct(sample, 1) * 1000) / 1000,
                distinct2: Math.round(distinct(sample, 2) * 1000) / 1000,
                humanNamePct: '-',
                hintNumbersKeptPct: null,
                hintRows: '-',
                replyTokens: null,
                genMs: null,
                passByVia: {}
            },
            perId: []
        };
    }
    const names = Object.keys(report);
    const table = [
        ['', ...names],
        ['answered', ...names.map(n => `${report[n].summary.answered} (${report[n].summary.answeredPct} %)`)],
        ["guard's pass (of answered)", ...names.map(n => `${report[n].summary.guardPassPct} %`)],
        ['all checks pass (of answered)', ...names.map(n => `${report[n].summary.passPct} %`)],
        ['guard refusals', ...names.map(n => JSON.stringify(report[n].summary.guardRefusals))],
        ['check failures', ...names.map(n => JSON.stringify(report[n].summary.checkFailures))],
        ['fact contradictions', ...names.map(n => `${report[n].summary.factContradictions} (${report[n].summary.factContradictionPct} %)`)],
        ["hint's numbers kept", ...names.map(n => `${report[n].summary.hintNumbersKeptPct ?? '-'} % of ${report[n].summary.hintRows}`)],
        ['chars mean / median', ...names.map(n => `${report[n].summary.chars.mean} / ${report[n].summary.chars.median}`)],
        ['words mean (1-3 / 4-8 / 9+ %)', ...names.map(n => `${report[n].summary.words.mean} (${report[n].summary.words['1-3']} / ${report[n].summary.words['4-8']} / ${report[n].summary.words['9+']})`)],
        ['all lower case', ...names.map(n => `${report[n].summary.lowercasePct} %`)],
        ['distinct-1 / distinct-2', ...names.map(n => `${report[n].summary.distinct1} / ${report[n].summary.distinct2}`)],
        ["the human's name", ...names.map(n => `${report[n].summary.humanNamePct} %`)],
        ['reply tokens mean', ...names.map(n => `${report[n].summary.replyTokens?.mean ?? '-'}`)],
        ['generation ms mean (M2)', ...names.map(n => `${report[n].summary.genMs?.mean ?? '-'}`)],
        ['pass by via', ...names.map(n => JSON.stringify(report[n].summary.passByVia))]
    ];
    for (const row of table) console.log(`| ${row.join(' | ')} |`);
    if (jsonOut) fs.writeFileSync(jsonOut, JSON.stringify(report, null, 1) + '\n');
}

if (command === 'gen') await generate();
else if (command === 'score') await score();
else {
    console.error('usage: eval.mjs gen --server=URL --variant=lora|base --out=FILE | eval.mjs score [--json=FILE] name=file ...');
    process.exit(2);
}
